C['gentle-unknot']={init(k){return{n:3,w:[...braidStudies[k]],selected:0}},render(c){const s=c.s;c.clue('A closed braid: bottom lane j reconnects to top lane j outside the diagram. Preserve its over/under topology.\nCrossing +j has lane j passing OVER lane j+1; −j has lane j+1 passing OVER lane j. A crossing exchanges those two lanes.\nGoal: one strand and zero crossings. '+s.n+' strands · '+s.w.length+' crossings.');let svg=`<svg viewBox="0 0 260 ${Math.max(100,s.w.length*30+45)}" role="img" aria-label="Closed braid diagram. Every signed crossing and its local move is listed as a numbered control.">`;for(let lane=0;lane<s.n;lane++)svg+=`<text x="${70+lane*55}" y="15" text-anchor="middle">lane ${lane+1}</text>`;s.w.forEach((g,i)=>{const left=Math.abs(g)-1,y=25+i*30,x=70+left*55;for(let lane=0;lane<s.n;lane++)if(lane!==left&&lane!==left+1)svg+=`<line x1="${70+lane*55}" y1="${y}" x2="${70+lane*55}" y2="${y+30}" stroke="#587867" stroke-width="3"/>`;svg+=`<path d="M${x},${y} L${x+55},${y+30} M${x+55},${y} L${x},${y+30}" fill="none" stroke="#587867" stroke-width="3"/><circle cx="${x+27.5}" cy="${y+15}" r="6" fill="#eeeee6"/>`;svg+=g>0?`<path d="M${x+16},${y+9} L${x+39},${y+21}" stroke="#284d3d" stroke-width="4"/>`:`<path d="M${x+39},${y+9} L${x+16},${y+21}" stroke="#284d3d" stroke-width="4"/>`;svg+=`<text x="15" y="${y+20}" font-size="13">${i+1}${i===s.selected?' ◀':''}</text>`});c.svg(svg+'</svg>');const group=c.group();s.w.forEach((g,i)=>c.button('cross-'+i,(i+1)+': '+(g>0?'+':'')+g,()=>c.select(()=>s.selected=i),{parent:group,pressed:s.selected===i}));c.text('Selected local region begins at crossing '+(s.selected+1)+'.\nCancel pair: +j,−j (or −j,+j) is a removable bigon. Slide triple: +1,+2,+1 ↔ +2,+1,+2, or the all-negative equivalent. This moves a strand past a crossing without passing through another strand.');c.button('braid-cancel','Cancel opposite crossing pair',()=>{const i=s.selected;if(i>=s.w.length-1||s.w[i]!==-s.w[i+1])return c.say('These consecutive crossings are not an inverse pair on the same two lanes. Topology prevents cancellation.');c.change(()=>{s.w.splice(i,2);s.selected=Math.max(0,Math.min(i,s.w.length-1))})});c.button('braid-slide','Slide strand across triple',()=>{const i=s.selected,[a,b,z]=s.w.slice(i,i+3);if(a!==z||Math.abs(Math.abs(a)-Math.abs(b))!==1||a*b<=0)return c.say('A slide needs three crossings a,b,a of the same sign on adjacent lane pairs.');c.change(()=>s.w.splice(i,3,b,a,b))});c.button('braid-seam','Move closure seam down one crossing',()=>{if(!s.w.length)return c.say('No crossing to move across the closure seam.');c.change(()=>{s.w.push(s.w.shift());s.selected=0})});c.button('braid-curl','Remove free final-strand curl',()=>{if(s.n<2||s.w.filter(g=>Math.abs(g)===s.n-1).length!==1||Math.abs(s.w.at(-1))!==s.n-1)return c.say('The last strand must participate in exactly one crossing, placed last beside the closure seam. Move the seam if needed.');c.change(()=>{s.w.pop();s.n--;s.selected=0})});c.button('braid-add','Insert a reversible crossing pair',()=>{if(s.w.length>=20)return c.say('The diagram is at its 20-crossing display limit; undo or simplify first.');if(s.n<2)return c.say('One plain loop is already ready to certify.');c.change(()=>{const g=Math.abs(s.w[s.selected]||1);s.w.splice(s.selected,0,g,-g)})});c.text('Moving the seam changes where you read the same closed braid, not its knot type. A final strand meeting the rest only once is a free curl: removing its sole crossing and that strand is a topology-preserving Reidemeister-I simplification. Undo reverses every edit.');},check(s){return s.n===1&&s.w.length===0?null:'The closed braid still has '+s.n+' strands and '+s.w.length+' crossings. Simplify to one plain loop; never discard a strand that has no crossing.'}};
const bondStudies=[{positions:[0,4,6],caps:[1,2,1],walls:[10,11,13,14],dock:[21,22,23],target:[[0,1],[1,2]],name:'Assemble beyond the narrow neck'},{positions:[0,4,6,8],caps:[1,3,1,1],walls:[10,11,13,14],dock:[16,17,18,22],target:[[0,1],[1,2],[1,3]],name:'A branched product'},{positions:[0,4,6,8],caps:[1,2,2,1],walls:[10,12,13,14],dock:[20,21,22,23],target:[[0,1],[1,2],[2,3]],name:'The offset passage'}];
function bondComponent(s,i){const seen=new Set([i]),q=[i];for(let t=0;t<q.length;t++)for(const[a,b]of s.edges){const j=a===q[t]?b:b===q[t]?a:-1;if(j>=0&&!seen.has(j)){seen.add(j);q.push(j)}}return [...seen]}
function bondMove(s,k,id,d){const q=bondStudies[k],component=bondComponent(s,id),[dx,dy]=flingDirs[d],next=clone(s);for(const i of component){const p=s.positions[i],x=p%5+dx,y=Math.floor(p/5)+dy,v=y*5+x;if(x<0||x>=5||y<0||y>=5||q.walls.includes(v)||s.positions.some((p,j)=>!component.includes(j)&&p===v))return null;next.positions[i]=v}const degree=i=>next.edges.filter(e=>e.includes(i)).length;for(let i=0;i<next.positions.length;i++)for(let j=i+1;j<next.positions.length;j++){if(!component.includes(i)&&!component.includes(j))continue;const a=next.positions[i],b=next.positions[j];if(Math.abs(a%5-b%5)+Math.abs(Math.floor(a/5)-Math.floor(b/5))===1&&!next.edges.some(e=>e[0]===i&&e[1]===j)&&degree(i)<q.caps[i]&&degree(j)<q.caps[j])next.edges.push([i,j])}next.edges.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);next.dead=next.edges.some(e=>!q.target.some(t=>t.join()===e.join()));return next}
C['bonding-room']={init(k){return{positions:[...bondStudies[k].positions],edges:[],selected:0,dead:false}},render(c){const s=c.s,q=bondStudies[c.stage];c.clue(q.name+'\nTarget bonds: '+q.target.map(([a,b])=>'ABCD'[a]+'–'+'ABCD'[b]).join(', ')+'. Put every product atom on the outlined dock.\nSelect any atom to control its WHOLE rigid component. A step joins touching atoms automatically if both have free valence. At simultaneous contacts, alphabetical atom-pair order decides bonding. No rotation or bond cutting.');const comp=bondComponent(s,s.selected),grid=c.grid(5);for(let p=0;p<25;p++){const i=s.positions.indexOf(p);c.button('bond-cell-'+p,i>=0?'ABCD'[i]+' '+(Math.floor(p/5)+1)+','+(p%5+1):q.walls.includes(p)?'wall':q.dock.includes(p)?'dock':'·',()=>{if(i>=0)c.select(()=>s.selected=i)},{parent:grid,pressed:i>=0&&comp.includes(i),disabled:i<0||s.dead,class:q.walls.includes(p)?'wall':q.dock.includes(p)?'goal':''})}const controls=c.group();flingDirs.forEach((d,i)=>c.button('bond-dir-'+i,d[2],()=>{const next=bondMove(s,c.stage,s.selected,i);if(!next)return c.say('A member of this rigid molecule would hit a wall, boundary or another atom. Nothing moved.');c.change(()=>Object.assign(s,next));if(s.dead)c.say('An irreversible wrong bond formed. Its occupied valence prevents the target graph. Undo this contact to recover.');},{parent:controls,disabled:s.dead}));c.table(['Atom','Position row,column','Used / capacity','Bonded neighbors'],s.positions.map((p,i)=>['ABCD'[i],`${Math.floor(p/5)+1},${p%5+1}`,s.edges.filter(e=>e.includes(i)).length+' / '+q.caps[i],s.edges.filter(e=>e.includes(i)).map(e=>'ABCD'[e[0]===i?e[1]:e[0]]).join(', ')||'none']));c.text('Selected component: '+comp.map(i=>'ABCD'[i]).join(', ')+'. A larger footprint may no longer pass a narrow neck. Components already touching do not bond spontaneously until one of them moves into contact.');},check(s,k){const q=bondStudies[k];if(s.dead)return'This molecule contains an irreversible bond outside the requested product. Undo or reset.';if(s.edges.length!==q.target.length||q.target.some(e=>!s.edges.some(t=>t.join()===e.join())))return'The required molecular graph is not assembled yet.';if(!s.positions.every(p=>q.dock.includes(p)))return'The product is correct but not entirely inside the delivery dock.';return null}};
function ruleLevel(k){const n=k===2?9:7,h=k===2?8:7,objects=[],add=(token,x,y,word=true)=>objects.push({token,x,y,word}),line=(tokens,x,y)=>tokens.forEach((t,i)=>add(t,x+i,y));let walls=[];if(k===0){line(['BABA','IS','YOU'],0,0);line(['ROCK','IS','PUSH'],0,2);add('WIN',4,3);add('BABA',4,4,false);add('ROCK',4,5,false);walls=[6,13,20,27,34,41,48]}if(k===1){for(let y=0;y<h;y++)walls.push(y*n+3);line(['BABA','IS','YOU'],0,2);line(['ROCK','IS'],0,3);line(['FLAG','IS','STOP'],4,3);add('WIN',6,4);add('BABA',2,1,false);add('ROCK',5,5,false);add('FLAG',4,5,false)}if(k===2){for(let y=0;y<h;y++)walls.push(y*n+4);line(['BABA','IS','YOU'],0,0);line(['ROCK','IS'],0,2);add('YOU',2,3);line(['FLAG','IS','STOP'],0,5);add('WIN',2,6);add('BABA',2,4,false);add('ROCK',7,6,false);add('FLAG',7,1,false)}return{n,h,walls,objects,dead:false,won:false}}
function worldRules(s){const rules={BABA:[],ROCK:[],FLAG:[],WALL:[]},wordAt=(x,y)=>s.objects.find(o=>o.word&&o.x===x&&o.y===y)?.token;for(const o of s.objects.filter(o=>o.word&&o.token==='IS'))for(const[dx,dy]of[[1,0],[0,1]]){const noun=wordAt(o.x-dx,o.y-dy),property=wordAt(o.x+dx,o.y+dy);if(rules[noun]&&['YOU','PUSH','STOP','WIN'].includes(property)&&!rules[noun].includes(property))rules[noun].push(property)}return rules}
function worldStep(s,d){const[dx,dy]=flingDirs[d],r=worldRules(s),plans=new Set();function attempt(i,set,seen){if(set.has(i))return true;if(seen.has(i))return false;const o=s.objects[i],x=o.x+dx,y=o.y+dy;if(x<0||x>=s.n||y<0||y>=s.h||s.walls.includes(y*s.n+x))return false;seen.add(i);for(let j=0;j<s.objects.length;j++){const q=s.objects[j];if(j===i||q.x!==x||q.y!==y)continue;if(q.word||r[q.token]?.includes('PUSH')){if(!attempt(j,set,seen))return false}else if(r[q.token]?.includes('STOP'))return false}set.add(i);return true}for(let i=0;i<s.objects.length;i++){const o=s.objects[i];if(o.word||!r[o.token]?.includes('YOU'))continue;const draft=new Set(plans);if(attempt(i,draft,new Set()))for(const p of draft)plans.add(p)}if(!plans.size)return null;const next=clone(s);for(const i of plans){next.objects[i].x+=dx;next.objects[i].y+=dy}const fresh=worldRules(next),you=next.objects.filter(o=>!o.word&&fresh[o.token]?.includes('YOU')),win=next.objects.filter(o=>!o.word&&fresh[o.token]?.includes('WIN'));next.dead=!you.length;next.won=you.some(o=>win.some(q=>o.x===q.x&&o.y===q.y));return next}
C['words-that-move']={init:ruleLevel,render(c){const s=c.s,r=worldRules(s);c.clue(['No flag in this room: make the rock a goal.','Transfer control across the sealed partition, then change what counts as a goal.','Keep both bodies controlled: one must change the left-hand goal rule while the other reaches the isolated flag.'][c.stage]+'\nWords in straight NOUN–IS–PROPERTY lines govern the objects. Every word is pushable. YOU moves all matching objects; PUSH makes objects pushable; STOP blocks; WIN wins on contact with any YOU. Blank property means none. Stone wall cells never move.');const grid=c.grid(s.n);for(let p=0;p<s.n*s.h;p++){const os=s.objects.filter(o=>o.x===p%s.n&&o.y===Math.floor(p/s.n));c.button('world-'+p,s.walls.includes(p)?'■':os.length?os.map(o=>o.word?'['+o.token+']':o.token.toLowerCase()).join('+'):'·',()=>c.say('Row '+(Math.floor(p/s.n)+1)+', column '+(p%s.n+1)+': '+(os.map(o=>(o.word?'word ':'object ')+o.token).join(', ')||'empty floor')),{parent:grid,class:s.walls.includes(p)?'wall':'',disabled:s.walls.includes(p)})}const controls=c.group();flingDirs.forEach((d,i)=>c.button('world-dir-'+i,d[2],()=>{const next=worldStep(s,i);if(!next)return c.say('Every controlled body is blocked; no object or word moved.');c.change(()=>Object.assign(s,next));c.say(s.won?'A controlled body touched a winning object. Certify the study.':s.dead?'No YOU rule remains. Undo restores control.':'Moved one step; rules are rebuilt from the new word positions.');},{parent:controls,disabled:s.dead||s.won}));c.text('ACTIVE RULES\n'+Object.entries(r).filter(([,v])=>v.length).map(([n,v])=>n+' IS '+v.join(' and ')).join('\n'),'extra','card');c.text('Controlled objects: '+s.objects.filter(o=>!o.word&&r[o.token]?.includes('YOU')).map(o=>o.token+' at '+(o.y+1)+','+(o.x+1)).join('; '));},check(s){return s.won?null:s.dead?'There is no controlled body. Undo the word move that removed YOU.':'No controlled body has touched a currently winning object yet.'}};
let movingRoomStudies=[{masks:[3,5,6,9,3,12,6,5,9],spare:3,targets:[4,8,2],budget:8},{masks:[5,3,6,9,5,3,6,12,9],spare:7,targets:[7,2,5],budget:9},{masks:[3,6,12,9,5,3,6,9,12],spare:5,targets:[8,1,6],budget:10}];
const rotateMask=m=>((m<<1)&15)|(m>>3),mazeDirs=[[0,-1,1,4],[1,0,2,8],[0,1,4,1],[-1,0,8,2]];
function mazeReach(s,start=s.p){const parent={[start]:-1},queue=[start];for(let i=0;i<queue.length;i++){const p=queue[i],x=p%3,y=Math.floor(p/3);for(const[dx,dy,a,b]of mazeDirs){const X=x+dx,Y=y+dy,q=Y*3+X;if(X>=0&&X<3&&Y>=0&&Y<3&&(s.tiles[p].mask&a)&&(s.tiles[q].mask&b)&&parent[q]===undefined){parent[q]=p;queue.push(q)}}}return{queue,parent}}
function mazeWalk(s,to){const{parent}=mazeReach(s);if(parent[to]===undefined)return null;const path=[];for(let p=to;p>=0;p=parent[p])path.push(p);const next=clone(s);for(const p of path.reverse()){next.p=p;if(next.progress<next.targets.length&&next.tiles[p].id===next.targets[next.progress])next.progress++}next.won=next.progress===next.targets.length&&next.tiles[next.p].id===0;const reachable=mazeReach(next).queue.map(p=>next.tiles[p].id);next.dead=next.used>=next.budget&&!next.won&&(!reachable.includes(0)||next.targets.slice(next.progress).some(id=>!reachable.includes(id)));return next}
function mazeInsert(s,port){if(s.last!==null&&Math.floor(s.last/2)===Math.floor(port/2)&&s.last!==port)return null;if(s.used>=s.budget)return null;const next=clone(s),group=Math.floor(port/2),reverse=port%2,ids=group<3?[0,1,2].map(x=>group*3+x):[0,1,2].map(y=>y*3+group-3);if(reverse)ids.reverse();const outgoing=next.tiles[ids[2]];for(let j=2;j>0;j--)next.tiles[ids[j]]=next.tiles[ids[j-1]];next.tiles[ids[0]]=next.spare;next.spare=outgoing;const pi=ids.indexOf(next.p);if(pi>=0)next.p=ids[(pi+1)%3];next.used++;next.last=port;if(next.progress<next.targets.length&&next.tiles[next.p].id===next.targets[next.progress])next.progress++;next.won=next.progress===next.targets.length&&next.tiles[next.p].id===0;const reachable=mazeReach(next).queue.map(p=>next.tiles[p].id);next.dead=next.used>=next.budget&&!next.won&&(!reachable.includes(0)||next.targets.slice(next.progress).some(id=>!reachable.includes(id)));return next}
C['rooms-in-motion']={init(k){const q=movingRoomStudies[k];return{tiles:q.masks.map((mask,id)=>({mask,id})),spare:{mask:q.spare,id:9},p:0,progress:0,targets:[...q.targets],budget:q.budget,used:0,last:null,dead:false,won:false}},render(c){const s=c.s,reach=mazeReach(s).queue,ports=m=>mazeDirs.filter(d=>m&d[2]).map(d=>['N','E','S','W'][mazeDirs.indexOf(d)]).join('');c.clue('Slide the rooms, then walk their passages.\nCollect room IDs '+s.targets.join(' → ')+', then return to home room 0. Objectives move WITH their tiles. Inserts '+s.used+'/'+s.budget+'.\nA doorway connects only when both neighboring tiles open toward each other. Select any reachable room to walk there along a shortest route. The ejected room becomes the next spare; a rider on it wraps to the inserted end.');const grid=c.grid(3);s.tiles.forEach((t,i)=>c.button('room-'+i,`${s.p===i?'YOU · ':''}room ${t.id}${t.id===0?' HOME':''}${s.targets[s.progress]===t.id?' ★':''}\n${ports(t.mask)}`,()=>{const next=mazeWalk(s,i);if(!next)return c.say('No connected corridor reaches that room from your position.');c.change(()=>Object.assign(s,next));if(s.won)c.say('All objectives collected and home reached. Certify the study.');},{parent:grid,pressed:s.p===i,class:reach.includes(i)?'goal':'',disabled:s.won}));c.text('Next spare: room '+s.spare.id+' · doors '+ports(s.spare.mask)+(s.targets[s.progress]===s.spare.id?' · NEXT OBJECTIVE is on this spare!':'')+'\nCollected '+s.progress+'/'+s.targets.length);c.button('rotate-spare','Rotate spare clockwise',()=>c.change(()=>s.spare.mask=rotateMask(s.spare.mask)),{disabled:s.won||s.used>=s.budget});const controls=c.group();for(let p=0;p<12;p++){const g=Math.floor(p/2),label=g<3?'Row '+(g+1)+' from '+(p%2?'right':'left'):'Column '+(g-2)+' from '+(p%2?'bottom':'top');c.button('insert-'+p,label,()=>{const next=mazeInsert(s,p);if(!next)return c.say('That would immediately reverse the last insertion, or the insertion budget is exhausted. Walk, change another lane, Undo or Reset.');c.change(()=>Object.assign(s,next));},{parent:controls,disabled:s.won||s.used>=s.budget})}c.text('Reachable coordinates: '+reach.map(p=>`${Math.floor(p/3)+1},${p%3+1}`).join('; ')+'. You may still walk after the final insertion.');},check(s){return s.won?null:s.used>=s.budget?'No insertions remain. Walk if home is connected; otherwise Undo or Reset.':'Collect all ordered room objectives and return to home room 0.'}};
function photoLevel(k){const n=k===2?8:7,b=Array(n*n).fill('#'),floor=(x,y)=>b[y*n+x]='.',origin=k===2?[4,4]:[3,3],start=k===2?[0,7]:[0,6],exit=k===1?[0,0]:[n-1,0];floor(...start);for(let i=0;i<3;i++){floor(origin[0]+i,origin[1]);floor(origin[0],origin[1]+i)}b[(origin[1]+1)*n+origin[0]+1]='K';if(k===0){for(let x=4;x<7;x++)floor(x,0)}if(k===1){for(let x=0;x<3;x++)floor(x,0)}if(k===2){floor(3,4);floor(7,1)}b[exit[1]*n+exit[0]]='E';return{n,b,p:start[1]*n+start[0],exit:exit[1]*n+exit[0],fixed:k===1?[2*n]:[],frame:0,photo:null,exposures:k===2?3:2,keys:0,need:k+2,mode:'walk',dead:false,won:false}}
function photoReach(s){const q=[s.p],seen=new Set(q),parents={[s.p]:-1};for(let i=0;i<q.length;i++){const p=q[i],x=p%s.n,y=Math.floor(p/s.n);for(const[dx,dy]of flingDirs){const X=x+dx,Y=y+dy,j=Y*s.n+X;if(X>=0&&X<s.n&&Y>=0&&Y<s.n&&s.b[j]!=='#'&&!seen.has(j)){seen.add(j);q.push(j);parents[j]=p}}}return{cells:q,parents}}
function photoRefresh(s){s.won=s.p===s.exit&&s.keys>=s.need;if(!s.photo&&s.exposures===0&&!s.won){const r=photoReach(s).cells;s.dead=!r.includes(s.exit)||s.keys+r.filter(p=>s.b[p]==='K').length<s.need}else s.dead=false}
function photoMove(s,d){const[dx,dy]=flingDirs[d],x=s.p%s.n+dx,y=Math.floor(s.p/s.n)+dy,p=y*s.n+x;if(x<0||x>=s.n||y<0||y>=s.n||s.b[p]==='#')return null;const next=clone(s);next.p=p;if(next.b[p]==='K'){next.keys++;next.b[p]='.'}photoRefresh(next);return next}
function photoPatchCells(s){const x=s.frame%s.n,y=Math.floor(s.frame/s.n);return Array.from({length:9},(_,i)=>(y+Math.floor(i/3))*s.n+x+i%3)}
function photoCapture(s){if(s.photo)return{error:'Use or discard the held photograph before exposing another.'};if(s.exposures<=0)return{error:'No exposures remain.'};const cells=photoPatchCells(s);if(cells.includes(s.p)||cells.includes(s.exit))return{error:'A snapshot cannot contain the avatar or the anchored exit.'};const next=clone(s);next.photo=cells.map(p=>s.b[p]);next.exposures--;return{next}}
function photoPaste(s){if(!s.photo)return{error:'Capture a photograph first.'};const cells=photoPatchCells(s);if(cells.includes(s.p)||cells.includes(s.exit))return{error:'Pasting cannot overwrite the avatar or the anchored exit.'};if(cells.some((p,i)=>s.fixed.includes(p)&&s.photo[i]!==s.b[p]))return{error:'A fixed masonry stud must keep its wall cell. Rotate or reposition the photograph.'};const next=clone(s);cells.forEach((p,i)=>next.b[p]=s.photo[i]);next.photo=null;photoRefresh(next);return{next}}
C['pocket-photograph']={init:photoLevel,render(c){const s=c.s,frame=photoPatchCells(s);c.clue(['Two bridges, two keys','A protected stud and three keys','A three-print expedition'][c.stage]+'\nReach E carrying '+s.need+' keys. Capture a LIVE 3×3 patch, then paste it elsewhere: every cell, including walls, REPLACES the destination. Keys can be copied before you collect them.\nExposures '+s.exposures+' · Keys '+s.keys+'/'+s.need+' · '+(s.photo?'One photograph held':'No photograph held')+(s.dead?'\nNo remaining photograph/exposure can complete this branch. Undo or reset.':''));const tools=c.group();for(const mode of['walk','frame'])c.button('photo-mode-'+mode,mode==='walk'?'Inspect / walk to adjacent cell':'Choose frame top-left',()=>c.select(()=>s.mode=mode),{parent:tools,pressed:s.mode===mode});const grid=c.grid(s.n);for(let p=0;p<s.b.length;p++){const x=p%s.n,y=Math.floor(p/s.n),label=p===s.p?'YOU':p===s.exit?'EXIT':s.fixed.includes(p)?'■ fixed':s.b[p]==='#'?'■':s.b[p]==='K'?'KEY':'·';c.button('photo-cell-'+p,label+' '+(y+1)+','+(x+1),()=>{if(s.mode==='frame'){if(x>s.n-3||y>s.n-3)return c.say('The whole 3×3 frame must fit on the board.');return c.select(()=>s.frame=p)}const dx=x-s.p%s.n,dy=y-Math.floor(s.p/s.n),d=flingDirs.findIndex(([a,b])=>a===dx&&b===dy);if(d<0)return c.say('Walking is one adjacent square at a time; use the directional controls.');const next=photoMove(s,d);if(!next)return c.say('That cell is wall. Nothing moved.');c.change(()=>Object.assign(s,next));},{parent:grid,pressed:s.mode==='frame'&&frame.includes(p),class:s.fixed.includes(p)?'goal':'',disabled:s.dead||s.won})}const controls=c.group();flingDirs.forEach((d,i)=>c.button('photo-dir-'+i,d[2],()=>{const next=photoMove(s,i);if(!next)return c.say('Wall or boundary blocks that step.');c.change(()=>Object.assign(s,next));},{parent:controls,disabled:s.dead||s.won}));c.text('Frame top-left: '+(Math.floor(s.frame/s.n)+1)+','+(s.frame%s.n+1)+'. Its nine current cells: '+frame.map(p=>s.b[p]).join(' '));c.button('capture','Capture frame',()=>{const r=photoCapture(s);if(r.error)return c.say(r.error);c.change(()=>Object.assign(s,r.next));},{disabled:s.dead||s.won});c.button('rotate-photo','Rotate held photo clockwise',()=>{if(!s.photo)return c.say('There is no photograph to rotate.');c.change(()=>{const old=[...s.photo];s.photo=old.map((_,i)=>old[(2-i%3)*3+Math.floor(i/3)])})},{disabled:!s.photo||s.dead||s.won});c.button('paste','Paste at frame',()=>{const r=photoPaste(s);if(r.error)return c.say(r.error);c.change(()=>Object.assign(s,r.next));c.say(s.dead?'The prints are spent and this layout cannot supply all keys and the exit. Undo to recover.':'Destination replaced, including empty wall cells. Inspect the new routes.');},{disabled:!s.photo||s.dead||s.won});c.text('HELD PHOTOGRAPH\n'+(s.photo?[0,1,2].map(y=>s.photo.slice(y*3,y*3+3).join(' ')).join('\n'):'none')+'\nLegend: . floor · # wall · K key. A photograph remembers capture-time state, not later changes at its source.','extra','card');c.text('The exit is anchored and cannot be captured or pasted over.'+(s.fixed.length?' Fixed masonry: '+s.fixed.map(p=>`${Math.floor(p/s.n)+1},${p%s.n+1}`).join('; ')+'. A pasted wall may cover a stud, but floor or key may not replace it.':''));},check(s){return s.won?null:s.dead?'This no-camera layout cannot reach the exit with enough keys. Undo a paste.':'Carry '+s.need+' keys to the anchored exit; currently '+s.keys+' keys.'}};
